// Host-fed matrix job datapath: iterator -> compute -> writeback -> C SRAM.
// The host writes the next operand tile to the inactive bank and pulses
// operands_ready. Coordinates and K length are generated by hardware.
module tensorforge_matrix_job_top #(
    parameter int N = 4,
    parameter int K_MAX = 32,
    parameter int ACC_W = 32,
    parameter int ADDR_W = $clog2(N*K_MAX)
) (
    input logic clk, rst_n, start, operands_ready, enable, mode_int4,
    input logic [15:0] m_dim, k_dim, p_dim,
    input logic a_write, b_write,
    input logic [ADDR_W-1:0] write_addr,
    input logic [7:0] write_data,
    input logic [15:0] read_row, read_col,
    output logic [ACC_W-1:0] read_data,
    output logic read_valid,
    output logic job_done, waiting_for_operands, waiting_for_engine,
    output logic waiting_for_writeback, engine_busy, writeback_busy,
    output logic active_bank,
    output logic [15:0] tile_row, tile_col, k_block,
    output logic [$clog2(K_MAX+1)-1:0] current_k_len,
    output logic first_k_block, last_k_block,
    output logic [31:0] tiles_visited, accepted_writes
);
    logic engine_start, engine_done, writeback_done;
    logic [N*N*ACC_W-1:0] results;
    logic [31:0] cycle_count, stall_count;
    logic wb_valid, wb_first, wb_accepted;
    logic [15:0] wb_row, wb_col;
    logic [$clog2(N)-1:0] wb_row_lane, wb_col_lane;
    logic [ACC_W-1:0] wb_data;
    logic [15:0] launched_row, launched_col;
    logic launched_first;
    always_ff @(posedge clk) begin
        if (!rst_n) begin
            launched_row <= '0;
            launched_col <= '0;
            launched_first <= 1'b0;
        end else if (engine_start) begin
            launched_row <= tile_row;
            launched_col <= tile_col;
            launched_first <= first_k_block;
        end
    end
    matrix_job_controller #(.N(N), .K_TILE(K_MAX)) controller (
        .clk(clk), .rst_n(rst_n), .start(start),
        .m_dim(m_dim), .k_dim(k_dim), .p_dim(p_dim),
        .operands_ready(operands_ready),
        .engine_busy(engine_busy), .engine_done(engine_done),
        .writeback_done(writeback_done), .engine_start(engine_start),
        .waiting_for_operands(waiting_for_operands),
        .waiting_for_engine(waiting_for_engine),
        .waiting_for_writeback(waiting_for_writeback),
        .job_done(job_done), .tile_row(tile_row),
        .tile_col(tile_col), .k_block(k_block),
        .current_k_len(current_k_len),
        .first_k_block(first_k_block), .last_k_block(last_k_block),
        .tiles_visited(tiles_visited)
    );
    double_buffered_tile_engine #(.N(N), .K_MAX(K_MAX), .ACC_W(ACC_W)) engine (
        .clk(clk), .rst_n(rst_n), .start(engine_start),
        .enable(enable), .mode_int4(mode_int4), .k_len(current_k_len),
        .a_write(a_write), .b_write(b_write),
        .write_addr(write_addr), .write_data(write_data),
        .busy(engine_busy), .done(engine_done), .active_bank(active_bank),
        .cycle_count(cycle_count), .stall_count(stall_count),
        .results(results)
    );
    tile_writeback_sequencer #(.N(N), .ACC_W(ACC_W)) serializer (
        .clk(clk), .rst_n(rst_n), .engine_done(engine_done),
        .engine_results(results), .tile_row(launched_row),
        .tile_col(launched_col), .first_k_block(launched_first),
        .busy(writeback_busy), .write_valid(wb_valid),
        .write_tile_row(wb_row), .write_tile_col(wb_col),
        .write_first_k_block(wb_first),
        .write_row_lane(wb_row_lane), .write_col_lane(wb_col_lane),
        .write_partial_sum(wb_data), .transfer_done(writeback_done)
    );
    output_accumulator #(.N(N), .ACC_W(ACC_W)) output_store (
        .clk(clk), .rst_n(rst_n), .m_dim(m_dim), .p_dim(p_dim),
        .write_valid(wb_valid), .first_k_block(wb_first),
        .tile_row(wb_row), .tile_col(wb_col),
        .row_lane(wb_row_lane), .col_lane(wb_col_lane),
        .partial_sum(wb_data), .write_accepted(wb_accepted),
        .read_row(read_row), .read_col(read_col),
        .read_data(read_data), .read_valid(read_valid),
        .accepted_writes(accepted_writes)
    );
endmodule
